/**
 * Deterministic export of the resolution register: CSV, JSONL and one
 * self-contained HTML page.
 *
 * Source of truth: DESIGN.md §7.4.7 (formats + determinism rules) and
 * UI.md §4.6 (the export dialog). This module is the *whole* generator: it is
 * pure, DOM-free and Node-safe so the same bytes can be produced in a browser,
 * asserted in a golden-file test and re-generated by a reviewer. The browser
 * wrapper only turns the chunks into a downloaded file
 * (`src/client/export/download.ts`).
 *
 * Purity contract (enforced by `tests/export/purity.spec.ts`):
 *
 * - no DOM, no Node built-ins, no network, no timers;
 * - no clock: the only time in an export is `options.generatedAt`; every other
 *   timestamp is derived from the records;
 * - no randomness, no `crypto`, no `uuid`;
 * - no locale or timezone dependence: all instants are formatted from UTC
 *   parts, sorting compares code units, and month/weekday names come from the
 *   frozen tables below (never `toLocaleString`);
 * - all line endings are LF; all text is UTF-8; all numbers use `.` decimals.
 *
 * Determinism rule: same records + same options ⇒ byte-identical output.
 * @module dsh-open-items/shared/export
 */
import type {
  Acknowledgement,
  AcknowledgementEvidence,
  DeliveryRecord,
  HistoryEntry,
  ItemSourceRef,
  OpenItemRecord,
  ReplyDescriptor,
  ReplyPayload,
  Resolution,
} from './schema'

/**
 * Version of the *file layout* (columns, keys, HTML DOM). Adding a field bumps
 * this; removing or reordering one is a breaking change (DESIGN §7.4.7 rule 3).
 */
export const EXPORT_SCHEMA_VERSION = 1

/** The three shipped encodings of one filtered result set. */
export type ExportFormat = 'csv' | 'jsonl' | 'html'

/** One export request, built by the dialog from the current filter. */
export interface ExportOptions {
  /** Encoding of the same result set. */
  readonly format: ExportFormat
  /** Include resolutions whose retention class is `archived` (older than 365 d). */
  readonly includeArchive: boolean
  /** Include transcript-derived text (`body` and `quote`). Default per format is decided by the dialog. */
  readonly includeExcerpts: boolean
  /** Human description of the active filter, e.g. `30 days · all sources`. */
  readonly filterLabel: string
  /** Export time in epoch milliseconds. The ONLY clock value in any output. */
  readonly generatedAt: number
  /** Version of the plugin that produced the file. */
  readonly pluginVersion: string
  /** Store schema version the records were read at (DESIGN schema v3). */
  readonly schemaVersion: number
  /** True when a retention cap pruned older rows: every header must say so. */
  readonly earlierRecordsPruned: boolean
}

/** MIME type per format (no charset guessing in the download wrapper). */
export const EXPORT_MIME_TYPES: Readonly<Record<ExportFormat, string>> = {
  csv: 'text/csv;charset=utf-8',
  jsonl: 'application/x-ndjson;charset=utf-8',
  html: 'text/html;charset=utf-8',
}

/** File extension per format. */
export const EXPORT_EXTENSIONS: Readonly<Record<ExportFormat, string>> = {
  csv: 'csv',
  jsonl: 'jsonl',
  html: 'html',
}

/** One generated file as a single string (the golden-file view). */
export interface ExportFile {
  readonly format: ExportFormat
  readonly filename: string
  readonly mimeType: string
  readonly content: string
  /** UTF-8 byte length of `content` (what the download will actually be). */
  readonly byteLength: number
}

/**
 * One generated file as ordered chunks. Large selections are assembled by the
 * browser into a `Blob` from these chunks instead of one giant string, which is
 * the "stream rows into a Blob" rule of DESIGN §7.4.7. `chunks.join('')` is
 * byte-identical to {@link generateExport}'s `content`.
 */
export interface ExportChunkSet {
  readonly format: ExportFormat
  readonly filename: string
  readonly mimeType: string
  readonly chunks: readonly string[]
  readonly byteLength: number
}

/** The filtered, ordered result set every format encodes. */
export interface ExportSelection {
  /** Sorted, filtered records: the exact rows in every format. */
  readonly records: readonly OpenItemRecord[]
  /** `resolvedAt` of the first (newest) row, or `undefined` when empty. */
  readonly newestResolvedAt: number | undefined
  /** How many included rows carry `retention.class === 'archived'` (text already dropped). */
  readonly archivedIncluded: number
  /** How many rows were dropped because they are archived and `includeArchive` is false. */
  readonly archivedExcluded: number
}

// ---------------------------------------------------------------------------
// Pure formatting helpers
// ---------------------------------------------------------------------------

/** Frozen English month names. Never `toLocaleString`: the export must not read the locale. */
const UTC_MONTHS: readonly string[] = [
  'January', 'February', 'March', 'April', 'May', 'June',
  'July', 'August', 'September', 'October', 'November', 'December',
]

/** Frozen English weekday names, indexed by UTC day of week (0 = Sunday). */
const UTC_WEEKDAYS: readonly string[] = [
  'Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday',
]

/** Two-digit zero pad without `Intl`. */
function pad2(value: number): string {
  return value < 10 ? `0${value}` : String(value)
}

/** Four-digit zero pad for years (years outside 0..9999 are not produced by the store). */
function pad4(value: number): string {
  const text = String(Math.trunc(value))
  return text.length >= 4 ? text : `${'0'.repeat(4 - text.length)}${text}`
}

/** Whether a value is a usable epoch-millisecond timestamp. */
function isTimestamp(value: unknown): value is number {
  return typeof value === 'number' && Number.isFinite(value) && Math.abs(value) <= 8.64e15
}

/**
 * ISO-8601 UTC instant with millisecond precision, e.g. `2026-11-13T22:41:00.000Z`.
 * Timezone-free by construction: every part is read from `Date#getUTC*`.
 * @param milliseconds - epoch milliseconds.
 * @returns the ISO string, or an empty string when the value is not a usable timestamp.
 */
export function isoUtc(milliseconds: number): string {
  if (!isTimestamp(milliseconds)) return ''
  const date = new Date(milliseconds)
  return `${pad4(date.getUTCFullYear())}-${pad2(date.getUTCMonth() + 1)}-${pad2(date.getUTCDate())}`
    + `T${pad2(date.getUTCHours())}:${pad2(date.getUTCMinutes())}:${pad2(date.getUTCSeconds())}`
    + `.${String(date.getUTCMilliseconds()).padStart(3, '0')}Z`
}

/**
 * Human-readable UTC instant for prose contexts, e.g. `2026-11-13 22:41 UTC`.
 * Seconds are included only when non-zero so row copy stays short.
 * @param milliseconds - epoch milliseconds.
 * @returns the display string, or `unknown time` when the value is unusable.
 */
export function formatUtcInstant(milliseconds: number): string {
  if (!isTimestamp(milliseconds)) return 'unknown time'
  const date = new Date(milliseconds)
  const day = `${pad4(date.getUTCFullYear())}-${pad2(date.getUTCMonth() + 1)}-${pad2(date.getUTCDate())}`
  const seconds = date.getUTCSeconds()
  const time = seconds === 0
    ? `${pad2(date.getUTCHours())}:${pad2(date.getUTCMinutes())}`
    : `${pad2(date.getUTCHours())}:${pad2(date.getUTCMinutes())}:${pad2(seconds)}`
  return `${day} ${time} UTC`
}

/**
 * UTC calendar day key (`YYYY-MM-DD`) used to group the HTML journal.
 * @param milliseconds - epoch milliseconds.
 * @returns the day key, or `unknown-day` when the value is unusable.
 */
export function utcDay(milliseconds: number): string {
  if (!isTimestamp(milliseconds)) return 'unknown-day'
  const date = new Date(milliseconds)
  return `${pad4(date.getUTCFullYear())}-${pad2(date.getUTCMonth() + 1)}-${pad2(date.getUTCDate())}`
}

/**
 * Compact UTC stamp safe in a file name, e.g. `20261113T224100Z`.
 * @param milliseconds - epoch milliseconds.
 * @returns the stamp, or `unknown` when the value is unusable.
 */
export function compactUtcStamp(milliseconds: number): string {
  const iso = isoUtc(milliseconds)
  return iso === '' ? 'unknown' : `${iso.slice(0, 4)}${iso.slice(5, 7)}${iso.slice(8, 10)}T${iso.slice(11, 13)}${iso.slice(14, 16)}${iso.slice(17, 19)}Z`
}

/**
 * Heading for one UTC day, e.g. `Thursday, 13 November 2026`.
 * @param day - day key from {@link utcDay}.
 * @returns the heading, or `Unknown day` when the key is not a date.
 */
export function formatDayHeading(day: string): string {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/u.exec(day)
  if (match === null) return 'Unknown day'
  const year = Number(match[1])
  const month = Number(match[2])
  const date = Number(match[3])
  if (month < 1 || month > 12 || date < 1 || date > 31) return 'Unknown day'
  const at = Date.UTC(year, month - 1, date)
  const weekday = UTC_WEEKDAYS[new Date(at).getUTCDay()] ?? ''
  const monthName = UTC_MONTHS[month - 1] ?? ''
  return `${weekday}, ${date} ${monthName} ${year}`
}

/** One acknowledgement evidence kind in prose (CSV cell and HTML). */
const ACKNOWLEDGEMENT_WORDS: Readonly<Record<AcknowledgementEvidence, string>> = {
  'tool-result': 'tool result',
  'turn-continued': 'continued turn',
  'call-retried': 'retried call',
  'goal-resumed': 'resumed goal',
  'task-completed': 'completed task',
  'next-turn': 'next turn',
}

/**
 * The acknowledgement state as one honest phrase. The register never claims
 * more than the evidence supports (DESIGN §7.4.2).
 * @param record - one resolved record.
 * @returns e.g. `acknowledged by retried call`, `no acknowledgement observed`.
 */
export function acknowledgementLabel(record: OpenItemRecord): string {
  const acknowledgement: Acknowledgement | undefined = record.acknowledgement
  const resolutionKind = latestResolution(record)?.kind
  // Dismissals and supersedes are not answers: nothing is expected to act on
  // them, so claiming "no acknowledgement observed" would be dishonest (DESIGN §7.4.2).
  const notAnAnswer = resolutionKind === 'dismissed' || resolutionKind === 'superseded'
  if (acknowledgement === undefined) return notAnAnswer ? 'n/a' : 'unknown'
  if (acknowledgement.state === 'observed') {
    const evidence = acknowledgement.evidence
    const word = evidence === undefined ? undefined : ACKNOWLEDGEMENT_WORDS[evidence.kind]
    return word === undefined ? 'acknowledged' : `acknowledged by ${word}`
  }
  if (notAnAnswer || resolutionKind === 'detected-closed') return 'n/a'
  if (acknowledgement.state === 'pending') return 'pending'
  return 'no acknowledgement observed'
}

/** Kind label shown to a reader (the chip word of the UI). */
const KIND_LABELS: Readonly<Record<OpenItemRecord['kind'], string>> = {
  decision: 'Decision',
  approval: 'Approval',
  question: 'Question',
  'plan-review': 'Plan review',
  blocker: 'Blocker',
  risk: 'Risk',
  'follow-up': 'Follow-up',
  task: 'Task',
}

/**
 * Human label for one item kind.
 * @param kind - the stored kind.
 * @returns the display word.
 */
export function kindLabel(kind: OpenItemRecord['kind']): string {
  return KIND_LABELS[kind]
}

/** `user` | `auto` — the two-channel source indicator of the Resolved tab. */
export type ExportSource = 'user' | 'auto'

/**
 * Which actor closed the item, in the export's two-channel vocabulary.
 * @param record - one resolved record.
 * @returns `user` when the user decided, `auto` when a detector did.
 */
export function sourceOf(record: OpenItemRecord): ExportSource {
  return record.resolution?.actor === 'detector' ? 'auto' : 'user'
}

/** Source word for prose contexts (`by you` / `automatic`). */
export function sourceLabel(record: OpenItemRecord): string {
  return sourceOf(record) === 'user' ? 'by you' : 'automatic'
}

/**
 * The decision itself, exactly as it was stored — never a paraphrase and never
 * model-generated (DESIGN §7.4.1).
 * @param payload - the stored resolution payload.
 * @returns one plain-text sentence fragment.
 */
export function payloadText(payload: ReplyPayload): string {
  switch (payload.type) {
    case 'option':
      return payload.option
    case 'text':
      return payload.text
    case 'approval':
      return payload.note === undefined || payload.note === ''
        ? (payload.outcome === 'allow-once' ? 'allowed once' : 'denied')
        : `${payload.outcome === 'allow-once' ? 'allowed once' : 'denied'} — note: ${payload.note}`
    case 'task-action':
      return payload.note === undefined || payload.note === ''
        ? payload.action
        : `${payload.action} — note: ${payload.note}`
    case 'dismiss':
      return payload.reason === undefined || payload.reason === '' ? 'dismissed' : `dismissed — ${payload.reason}`
    default:
      return ''
  }
}

/**
 * The "what was decided" cell for one record, including detector closes.
 * @param record - one resolved record.
 * @returns the decision text, or an empty string when the record has no resolution.
 */
export function decisionText(record: OpenItemRecord): string {
  const resolution = latestResolution(record)
  if (resolution === undefined) return ''
  const payload = resolution.payload
  if (payload.type === 'detector') return payload.code
  return payloadText(payload)
}

/**
 * Outcome word for one record: `answered` | `dismissed` | `superseded` | `detected-closed`.
 * @param record - one resolved record.
 * @returns the outcome, or `unknown` when the record has no resolution.
 */
export function outcomeOf(record: OpenItemRecord): string {
  return latestResolution(record)?.kind ?? 'unknown'
}

/**
 * Latest resolution: `resolution` is authoritative, and `resolutionLog` keeps
 * earlier cycles for re-import (§7.4.3 history integrity).
 * @param record - one resolved record.
 * @returns the current resolution when present.
 */
export function latestResolution(record: OpenItemRecord): Resolution | undefined {
  if (record.resolution !== undefined) return record.resolution
  const log = record.resolutionLog
  return log === undefined || log.length === 0 ? undefined : log[log.length - 1]
}

/**
 * Resolved-at of one record: `resolvedAt` is authoritative; a record whose
 * `resolution` carries the time is accepted as a fallback.
 * @param record - one resolved record.
 * @returns epoch milliseconds, or `undefined` when the record has no usable time.
 */
export function resolvedAtOf(record: OpenItemRecord): number | undefined {
  if (isTimestamp(record.resolvedAt)) return record.resolvedAt
  const resolution = latestResolution(record)
  return resolution !== undefined && isTimestamp(resolution.at) ? resolution.at : undefined
}

/**
 * Whether one record belongs in the export selection: resolved, with a usable
 * timestamp and not permanently deleted.
 * @param record - candidate record.
 * @returns true when the record is exportable.
 */
export function isExportable(record: OpenItemRecord): boolean {
  return record.state === 'resolved'
    && record.deletedAt === undefined
    && resolvedAtOf(record) !== undefined
    && latestResolution(record) !== undefined
}

/**
 * Stable export order: `resolvedAt` descending, tie-broken by item id ascending.
 * Compares code units directly so the order does not depend on the locale.
 * @param records - records in any order.
 * @returns a new sorted array (does not mutate the input).
 */
export function sortForExport(records: readonly OpenItemRecord[]): OpenItemRecord[] {
  const keyed = records.map(record => ({ record, at: resolvedAtOf(record) ?? Number.NEGATIVE_INFINITY }))
  keyed.sort((left, right) => {
    if (left.at !== right.at) return left.at > right.at ? -1 : 1
    if (left.record.id === right.record.id) return 0
    return left.record.id < right.record.id ? -1 : 1
  })
  return keyed.map(entry => entry.record)
}

/**
 * Apply the filter described by {@link ExportOptions}: exportable records only,
 * archive included or excluded, then stable ordering.
 * @param records - records in any order.
 * @param options - the export request.
 * @returns the selection every format encodes.
 */
export function selectExportRecords(
  records: readonly OpenItemRecord[],
  options: ExportOptions,
): ExportSelection {
  const exportable = records.filter(isExportable)
  const included = options.includeArchive
    ? exportable
    : exportable.filter(record => record.retention.class === 'active')
  const archivedExcluded = exportable.length - included.length
  const sorted = sortForExport(included)
  const first = sorted[0]
  return {
    records: sorted,
    newestResolvedAt: first === undefined ? undefined : resolvedAtOf(first),
    archivedIncluded: sorted.filter(record => record.retention.class === 'archived').length,
    archivedExcluded,
  }
}

// ---------------------------------------------------------------------------
// File name
// ---------------------------------------------------------------------------

/** FNV-1a over the UTF-16 code units: a tiny deterministic hash with no crypto import. */
function fnv1a(text: string): string {
  let hash = 0x811c9dc5
  for (let index = 0; index < text.length; index += 1) {
    hash ^= text.charCodeAt(index)
    hash = Math.imul(hash, 0x01000193) >>> 0
  }
  return hash.toString(16).padStart(8, '0')
}

/**
 * File-name slug of the filter label: lowercase ASCII alphanumerics joined by
 * single dashes. A label that yields no ASCII *letters* (e.g. `30 天`, or a bare
 * `30`) becomes `filter-<hash>` so two different filters cannot collide on one
 * name and a date-like number never names a file alone.
 * @param filterLabel - human filter description.
 * @returns a deterministic slug, never empty.
 */
export function filterSlug(filterLabel: string): string {
  const slug = filterLabel
    .toLowerCase()
    .replace(/[^a-z0-9]+/gu, '-')
    .replace(/^-+|-+$/gu, '')
    .slice(0, 40)
    .replace(/-+$/u, '')
  return slug === '' || !/[a-z]/u.test(slug) ? `filter-${fnv1a(filterLabel)}` : slug
}

/**
 * Deterministic file name: `open-items-<newest-resolvedAt>-<count>-<filter-slug>.<ext>`.
 * A repeated identical export overwrites the same name rather than inventing a
 * random suffix (DESIGN §7.4.7).
 * @param selection - the filtered result set.
 * @param options - the export request (format picks the extension).
 * @returns the file name.
 */
export function exportFileName(selection: ExportSelection, options: ExportOptions): string {
  const stamp = selection.newestResolvedAt === undefined ? 'empty' : compactUtcStamp(selection.newestResolvedAt)
  return `open-items-${stamp}-${selection.records.length}-${filterSlug(options.filterLabel)}.${EXPORT_EXTENSIONS[options.format]}`
}

// ---------------------------------------------------------------------------
// CSV
// ---------------------------------------------------------------------------

/**
 * Fixed CSV column order (export schema 1). Documented in the file header
 * comment as well, because a consumer reading the file has no other contract.
 */
export const CSV_COLUMNS: readonly string[] = [
  'resolvedAt',
  'sessionTitle',
  'sessionId',
  'itemId',
  'title',
  'kind',
  'severity',
  'outcome',
  'decision',
  'source',
  'acknowledged',
  'archived',
  // The two transcript-derived columns stay in the fixed order and are empty
  // when the export excludes excerpts, so the schema does not change per export.
  'excerpt',
  'quote',
]

/** Characters that make a spreadsheet treat a cell as a formula. */
const FORMULA_LEADERS = /^[=+\-@\t\r]/u

/**
 * One RFC 4180-ish cell: minimal quoting, `""` for an embedded quote, and
 * formula neutralization for spreadsheet injection. A value that starts with
 * `=`, `+`, `-`, `@`, tab or CR is prefixed with a single quote so Excel and
 * LibreOffice render it as text instead of executing it.
 * @param value - raw cell value.
 * @returns the escaped cell.
 */
export function csvCell(value: string): string {
  const normalized = value.replace(/\r\n?/gu, '\n')
  const neutralized = FORMULA_LEADERS.test(normalized) ? `'${normalized}` : normalized
  const needsQuotes = /[",\n]/u.test(neutralized) || /^\s|\s$/u.test(neutralized)
  if (!needsQuotes) return neutralized
  return `"${neutralized.replace(/"/gu, '""')}"`
}

/**
 * One CSV row from already-ordered cells.
 * @param cells - cell values in {@link CSV_COLUMNS} order.
 * @returns the row without a line terminator.
 */
export function csvRow(cells: readonly string[]): string {
  return cells.map(csvCell).join(',')
}

/** Honest header facts shared by all three formats. */
interface ExportFacts {
  readonly recordCount: number
  readonly archivedIncluded: number
  readonly archivedExcluded: number
  readonly generatedAt: string
}

/** Facts derived once per export. */
function factsOf(selection: ExportSelection, options: ExportOptions): ExportFacts {
  return {
    recordCount: selection.records.length,
    archivedIncluded: selection.archivedIncluded,
    archivedExcluded: selection.archivedExcluded,
    generatedAt: isoUtc(options.generatedAt),
  }
}

/**
 * The CSV comment row: export schema, plugin version, filter, counts and the
 * completeness flags. One line, so a reader can skip it with `grep -v '^#'`.
 * @param selection - filtered result set.
 * @param options - export request.
 * @returns the `#`-prefixed comment line without a terminator.
 */
export function csvHeaderComment(selection: ExportSelection, options: ExportOptions): string {
  const facts = factsOf(selection, options)
  const pruned = options.earlierRecordsPruned ? 'earlier-records-pruned' : 'nothing-pruned'
  const excerpts = options.includeExcerpts ? 'excerpts-included' : 'excerpts-excluded'
  const archive = options.includeArchive
    ? `archive-included(${String(facts.archivedIncluded)}-compacted)`
    : `archive-excluded(${String(facts.archivedExcluded)}-omitted)`
  return `# dsh-open-items register export · exportSchema=${String(EXPORT_SCHEMA_VERSION)}`
    + ` · storeSchema=${String(options.schemaVersion)} · plugin=${options.pluginVersion}`
    + ` · generatedAt=${facts.generatedAt} · filter=${quoteFact(options.filterLabel)}`
    + ` · records=${String(facts.recordCount)} · ${archive} · ${excerpts} · ${pruned}`
    // `|` rather than `,` so the comment row is exactly one CSV cell.
    + ` · columns=${CSV_COLUMNS.join('|')}`
}

/**
 * Quote one header fact so a `·`-separated header stays one CSV cell.
 * The comment row must contain neither a double quote (a reader that does not
 * skip `#` lines would treat the row as a quoted field) nor a comma (it would
 * split). Single quotes are ordinary characters in RFC 4180, so wrapping in
 * them is safe, and a comma inside a label is shown as `;`.
 */
function quoteFact(value: string): string {
  const flattened = value
    .replace(/\s+/gu, ' ')
    .replace(/["']/gu, ' ')
    .replace(/,/gu, ';')
    .replace(/ +/gu, ' ')
    .trim()
  return flattened === '' ? '(none)' : `'${flattened}'`
}

/**
 * One CSV row per resolution, in the fixed column order.
 * @param selection - filtered result set.
 * @param options - export request.
 * @returns rows without terminators.
 */
export function csvRows(selection: ExportSelection, options: ExportOptions): string[] {
  return selection.records.map((record) => {
    const resolution = latestResolution(record)
    const sessionTitle = record.source.sessionTitle
    return csvRow([
      isoUtc(resolvedAtOf(record) ?? Number.NaN),
      sessionTitle === undefined || sessionTitle === '' ? '(untitled session)' : sessionTitle,
      record.source.sessionId,
      record.id,
      record.title,
      record.kind,
      String(record.severity),
      resolution?.kind ?? 'unknown',
      decisionText(record),
      sourceOf(record),
      acknowledgementLabel(record),
      record.retention.class === 'archived' ? 'true' : 'false',
      options.includeExcerpts ? record.body : '',
      options.includeExcerpts ? (record.quote ?? '') : '',
    ])
  })
}

/**
 * Deterministic CSV: one header comment row, one column row, one row per
 * resolution, LF line endings, trailing LF.
 * @param records - records in any order (filtering and ordering are applied here).
 * @param options - export request.
 * @returns the complete file content.
 */
export function toCsv(records: readonly OpenItemRecord[], options: ExportOptions): string {
  return csvChunks(selectExportRecords(records, options), options).join('')
}

/** Chunked CSV: the header comment, the column row and each data row. */
function csvChunks(selection: ExportSelection, options: ExportOptions): string[] {
  const chunks: string[] = [`${csvHeaderComment(selection, options)}\n`, `${CSV_COLUMNS.join(',')}\n`]
  for (const row of csvRows(selection, options)) chunks.push(`${row}\n`)
  return chunks
}

// ---------------------------------------------------------------------------
// JSONL
// ---------------------------------------------------------------------------

/**
 * Fixed key order of one JSONL record line (export schema 1). Every line is a
 * complete record so a file can be split, sorted or imported line by line.
 */
export const JSONL_RECORD_KEYS: readonly string[] = [
  'type',
  'exportSchemaVersion',
  'schemaVersion',
  'id',
  'origin',
  'kind',
  'state',
  'tier',
  'severity',
  'title',
  'body',
  'quote',
  'options',
  'source',
  'blocking',
  'reply',
  'deliveries',
  'occurrences',
  'dedupeKey',
  'detectedBy',
  'firstSeenAt',
  'lastSeenAt',
  'updatedAt',
  'version',
  'snoozedUntil',
  'resolution',
  'resolutionLog',
  'acknowledgement',
  'resolvedAt',
  'reopenCount',
  'retention',
  'history',
  'deletedAt',
]

/** Keys the JSONL header line carries. */
export const JSONL_HEADER_KEYS: readonly string[] = [
  'type',
  'exportSchemaVersion',
  'schemaVersion',
  'pluginVersion',
  'generatedAt',
  'filterLabel',
  'recordCount',
  'earlierRecordsPruned',
  'includeArchive',
  'includeExcerpts',
  'archivedIncluded',
  'archivedExcluded',
]

/** One ordered JSON object as a single line. */
function jsonLine(entries: readonly (readonly [string, unknown])[]): string {
  return JSON.stringify(Object.fromEntries(entries))
}

/** Include an optional value only when it is defined (keeps key order stable). */
function optional(entries: (readonly [string, unknown])[], key: string, value: unknown): void {
  if (value !== undefined) entries.push([key, value])
}

/** Ordered JSON for a source reference. */
function sourceEntries(source: ItemSourceRef): (readonly [string, unknown])[] {
  const entries: (readonly [string, unknown])[] = [
    ['sessionId', source.sessionId],
  ]
  optional(entries, 'sessionTitle', source.sessionTitle)
  if (source.workspace !== undefined) {
    const workspace: (readonly [string, unknown])[] = []
    optional(workspace, 'workspaceId', source.workspace.workspaceId)
    optional(workspace, 'title', source.workspace.title)
    optional(workspace, 'path', source.workspace.path)
    entries.push(['workspace', Object.fromEntries(workspace)])
  }
  optional(entries, 'cwd', source.cwd)
  optional(entries, 'seq', source.seq)
  optional(entries, 'turn', source.turn)
  optional(entries, 'callId', source.callId)
  optional(entries, 'messageId', source.messageId)
  optional(entries, 'approvalId', source.approvalId)
  optional(entries, 'goalId', source.goalId)
  optional(entries, 'goalRevision', source.goalRevision)
  optional(entries, 'taskId', source.taskId)
  optional(entries, 'jobId', source.jobId)
  if (source.raisedBy !== undefined) {
    const raisedBy: (readonly [string, unknown])[] = [['sessionId', source.raisedBy.sessionId]]
    optional(raisedBy, 'title', source.raisedBy.title)
    entries.push(['raisedBy', Object.fromEntries(raisedBy)])
  }
  return entries
}

/** Ordered JSON for a reply descriptor. */
function replyEntries(reply: ReplyDescriptor): (readonly [string, unknown])[] {
  const entries: (readonly [string, unknown])[] = [
    ['controls', [...reply.controls]],
    ['freeText', reply.freeText],
    ['requiresConfirm', reply.requiresConfirm],
  ]
  optional(entries, 'options', reply.options === undefined ? undefined : [...reply.options])
  optional(entries, 'note', reply.note)
  return entries
}

/** Ordered JSON for a reply payload. */
function payloadEntries(payload: ReplyPayload): (readonly [string, unknown])[] {
  switch (payload.type) {
    case 'option': {
      const entries: (readonly [string, unknown])[] = [['type', payload.type], ['option', payload.option]]
      return entries
    }
    case 'text':
      return [['type', payload.type], ['text', payload.text]]
    case 'approval': {
      const entries: (readonly [string, unknown])[] = [['type', payload.type], ['outcome', payload.outcome]]
      optional(entries, 'note', payload.note)
      return entries
    }
    case 'task-action': {
      const entries: (readonly [string, unknown])[] = [['type', payload.type], ['action', payload.action]]
      optional(entries, 'note', payload.note)
      return entries
    }
    case 'dismiss': {
      const entries: (readonly [string, unknown])[] = [['type', payload.type]]
      optional(entries, 'reason', payload.reason)
      return entries
    }
    default:
      return [['type', 'unknown']]
  }
}

/** Ordered JSON for one delivery record. */
function deliveryEntries(delivery: DeliveryRecord): (readonly [string, unknown])[] {
  const entries: (readonly [string, unknown])[] = [
    ['deliveryId', delivery.deliveryId],
    ['at', delivery.at],
    ['track', delivery.track],
    ['payload', Object.fromEntries(payloadEntries(delivery.payload))],
    ['state', delivery.state],
  ]
  if (delivery.evidence !== undefined) {
    const evidence: (readonly [string, unknown])[] = []
    optional(evidence, 'seq', delivery.evidence.seq)
    optional(evidence, 'messageId', delivery.evidence.messageId)
    optional(evidence, 'callId', delivery.evidence.callId)
    optional(evidence, 'inboxId', delivery.evidence.inboxId)
    entries.push(['evidence', Object.fromEntries(evidence)])
  }
  if (delivery.failure !== undefined) {
    entries.push(['failure', { code: delivery.failure.code, message: delivery.failure.message }])
  }
  return entries
}

/** Ordered JSON for one resolution. */
function resolutionEntries(resolution: Resolution): (readonly [string, unknown])[] {
  const payload = resolution.payload
  const payloadValue = payload.type === 'detector'
    ? Object.fromEntries([['type', payload.type], ['code', payload.code]] as (readonly [string, unknown])[])
    : Object.fromEntries(payloadEntries(payload))
  const entries: (readonly [string, unknown])[] = [
    ['kind', resolution.kind],
    ['at', resolution.at],
    ['actor', resolution.actor],
    ['payload', payloadValue],
  ]
  optional(entries, 'deliveryId', resolution.deliveryId)
  if (resolution.evidence !== undefined) {
    const evidence: (readonly [string, unknown])[] = []
    optional(evidence, 'seq', resolution.evidence.seq)
    optional(evidence, 'messageId', resolution.evidence.messageId)
    optional(evidence, 'callId', resolution.evidence.callId)
    optional(evidence, 'inboxId', resolution.evidence.inboxId)
    entries.push(['evidence', Object.fromEntries(evidence)])
  }
  return entries
}

/** Ordered JSON for one acknowledgement. */
function acknowledgementEntries(acknowledgement: Acknowledgement): (readonly [string, unknown])[] {
  const entries: (readonly [string, unknown])[] = [['state', acknowledgement.state]]
  optional(entries, 'at', acknowledgement.at)
  if (acknowledgement.evidence !== undefined) {
    const evidence: (readonly [string, unknown])[] = [['kind', acknowledgement.evidence.kind]]
    optional(evidence, 'seq', acknowledgement.evidence.seq)
    entries.push(['evidence', Object.fromEntries(evidence)])
  }
  return entries
}

/** Ordered JSON for one history entry. */
function historyEntries(entry: HistoryEntry): (readonly [string, unknown])[] {
  const entries: (readonly [string, unknown])[] = [['at', entry.at], ['action', entry.action]]
  optional(entries, 'detail', entry.detail)
  return entries
}

/**
 * One full record as ordered JSON entries, honouring the excerpt option: with
 * `includeExcerpts: false` the transcript-derived `body` and `quote` are
 * omitted (not blanked), which is what "excerpts excluded" means.
 */
function recordEntries(record: OpenItemRecord, options: ExportOptions): (readonly [string, unknown])[] {
  const entries: (readonly [string, unknown])[] = [
    ['type', 'register-entry'],
    ['exportSchemaVersion', EXPORT_SCHEMA_VERSION],
    ['schemaVersion', record.schemaVersion],
    ['id', record.id],
    ['origin', record.origin],
    ['kind', record.kind],
    ['state', record.state],
    ['tier', record.tier],
    ['severity', record.severity],
    ['title', record.title],
  ]
  if (options.includeExcerpts) entries.push(['body', record.body])
  if (options.includeExcerpts) optional(entries, 'quote', record.quote)
  optional(entries, 'options', record.options === undefined ? undefined : [...record.options])
  entries.push(
    ['source', Object.fromEntries(sourceEntries(record.source))],
    ['blocking', record.blocking],
    ['reply', Object.fromEntries(replyEntries(record.reply))],
    ['deliveries', record.deliveries.map(delivery => Object.fromEntries(deliveryEntries(delivery)))],
    ['occurrences', record.occurrences.map(occurrence => Object.fromEntries(
      occurrence.seq === undefined
        ? [['sessionId', occurrence.sessionId], ['seenAt', occurrence.seenAt]] as (readonly [string, unknown])[]
        : [['sessionId', occurrence.sessionId], ['seq', occurrence.seq], ['seenAt', occurrence.seenAt]] as (readonly [string, unknown])[],
    ))],
    ['dedupeKey', record.dedupeKey],
    ['detectedBy', [...record.detectedBy]],
    ['firstSeenAt', record.firstSeenAt],
    ['lastSeenAt', record.lastSeenAt],
    ['updatedAt', record.updatedAt],
    ['version', record.version],
  )
  optional(entries, 'snoozedUntil', record.snoozedUntil)
  if (record.resolution !== undefined) entries.push(['resolution', Object.fromEntries(resolutionEntries(record.resolution))])
  if (record.resolutionLog !== undefined) {
    entries.push(['resolutionLog', record.resolutionLog.map(entry => Object.fromEntries(resolutionEntries(entry)))])
  }
  if (record.acknowledgement !== undefined) {
    entries.push(['acknowledgement', Object.fromEntries(acknowledgementEntries(record.acknowledgement))])
  }
  optional(entries, 'resolvedAt', record.resolvedAt)
  entries.push(['reopenCount', record.reopenCount])
  entries.push(['retention', Object.fromEntries(
    record.retention.archivedAt === undefined
      ? [['class', record.retention.class]] as (readonly [string, unknown])[]
      : [['class', record.retention.class], ['archivedAt', record.retention.archivedAt]] as (readonly [string, unknown])[],
  )])
  entries.push(['history', record.history.map(entry => Object.fromEntries(historyEntries(entry)))])
  optional(entries, 'deletedAt', record.deletedAt)
  return entries
}

/**
 * JSONL header line: the same honest facts as the CSV comment and the HTML
 * header, so a file with no comment syntax still describes itself.
 */
export function jsonlHeaderLine(selection: ExportSelection, options: ExportOptions): string {
  const facts = factsOf(selection, options)
  return jsonLine([
    ['type', 'export-header'],
    ['exportSchemaVersion', EXPORT_SCHEMA_VERSION],
    ['schemaVersion', options.schemaVersion],
    ['pluginVersion', options.pluginVersion],
    ['generatedAt', facts.generatedAt],
    ['filterLabel', options.filterLabel],
    ['recordCount', facts.recordCount],
    ['earlierRecordsPruned', options.earlierRecordsPruned],
    ['includeArchive', options.includeArchive],
    ['includeExcerpts', options.includeExcerpts],
    ['archivedIncluded', facts.archivedIncluded],
    ['archivedExcluded', facts.archivedExcluded],
  ])
}

/**
 * One JSONL record line with the fixed key order of {@link JSONL_RECORD_KEYS}.
 * @param record - one resolved record.
 * @param options - export request (controls excerpts only).
 * @returns the line without a terminator.
 */
export function jsonlRecordLine(record: OpenItemRecord, options: ExportOptions): string {
  return jsonLine(recordEntries(record, options))
}

/** Chunked JSONL: the header line and one line per record. */
function jsonlChunks(selection: ExportSelection, options: ExportOptions): string[] {
  const chunks: string[] = [`${jsonlHeaderLine(selection, options)}\n`]
  for (const record of selection.records) chunks.push(`${jsonlRecordLine(record, options)}\n`)
  return chunks
}

/**
 * Deterministic JSONL: header line, one full record per line, LF, trailing LF.
 * @param records - records in any order.
 * @param options - export request.
 * @returns the complete file content.
 */
export function toJsonl(records: readonly OpenItemRecord[], options: ExportOptions): string {
  return jsonlChunks(selectExportRecords(records, options), options).join('')
}

// ---------------------------------------------------------------------------
// HTML — frozen token map and stylesheet
// ---------------------------------------------------------------------------

/** One semantic colour pair of the exported page: the frozen light/dark pair. */
export interface ExportToken {
  /** CSS custom-property suffix (`--oi-<name>`). */
  readonly name: string
  /** Hex colour used when the reader's system prefers light. */
  readonly light: string
  /** Hex colour used inside `@media (prefers-color-scheme: dark)`. */
  readonly dark: string
}

/**
 * Pinned token snapshot for exported HTML (DESIGN §7.4.7 rule 4). This is a
 * frozen copy, not a read of the live DSH theme: a theme edit must never change
 * a file that was exported earlier. Editing this map changes exports, which is
 * why a snapshot test pins the compiled stylesheet.
 */
export const EXPORT_TOKENS: readonly ExportToken[] = [
  { name: 'canvas', light: '#ffffff', dark: '#141618' },
  { name: 'surface', light: '#f6f7f9', dark: '#1c1f22' },
  { name: 'border', light: '#d9dce1', dark: '#33383e' },
  { name: 'text', light: '#1a1c1f', dark: '#e7eaee' },
  { name: 'text-secondary', light: '#5b6169', dark: '#a8aeb6' },
  { name: 'text-tertiary', light: '#7b828b', dark: '#8d949d' },
  { name: 'accent', light: '#2f6fd0', dark: '#7fa9ec' },
  { name: 'user', light: '#1d7a4b', dark: '#63c995' },
  { name: 'auto', light: '#715bb8', dark: '#b49be8' },
  { name: 'warning', light: '#8a6200', dark: '#dcb35e' },
]

/** Print-only ink/paper pair, kept out of the dark-mode block. */
const PRINT_TOKENS: readonly { readonly name: string; readonly value: string }[] = [
  { name: 'print-ink', value: '#000000' },
  { name: 'print-paper', value: '#ffffff' },
]

/**
 * Compile the frozen token map into one minified stylesheet. Deterministic:
 * the token order above is the declaration order, and there are no other inputs.
 * @returns a single minified CSS string (no newlines, no external references).
 */
export function buildStylesheet(): string {
  const light = EXPORT_TOKENS.map(token => `--oi-${token.name}:${token.light}`).join(';')
  const dark = EXPORT_TOKENS.map(token => `--oi-${token.name}:${token.dark}`).join(';')
  const print = PRINT_TOKENS.map(token => `--oi-${token.name}:${token.value}`).join(';')
  const rules = [
    `:root{${light};${print};color-scheme:light dark}`,
    `@media (prefers-color-scheme:dark){:root{${dark}}}`,
    '*{box-sizing:border-box}',
    'html{-webkit-text-size-adjust:100%}',
    'body{margin:0;padding:32px 20px 48px;background:var(--oi-canvas);color:var(--oi-text);'
      + 'font:15px/1.55 system-ui,-apple-system,"Segoe UI",Roboto,sans-serif}',
    'header,main,footer{max-width:820px;margin:0 auto}',
    'h1{margin:0 0 4px;font-size:24px;line-height:1.25}',
    'h2{margin:32px 0 12px;font-size:15px;letter-spacing:.06em;text-transform:uppercase;'
      + 'color:var(--oi-text-secondary)}',
    'h3{margin:0 0 6px;font-size:16px;line-height:1.35}',
    'p{margin:0 0 10px}',
    'figure{margin:0}',
    'dl{margin:0 0 10px}',
    'dt{float:left;clear:left;width:34%;color:var(--oi-text-tertiary);font-size:12px;'
      + 'text-transform:uppercase;letter-spacing:.04em}',
    'dd{margin:0 0 4px 36%;font-size:13px;color:var(--oi-text-secondary)}',
    'dd::after{content:"";display:block;clear:both}',
    'code{font:12.5px/1.4 ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;'
      + 'color:var(--oi-text-tertiary)}',
    'time{font-variant-numeric:tabular-nums}',
    'article{margin:0 0 14px;padding:14px 16px;background:var(--oi-surface);'
      + 'border:1px solid var(--oi-border);border-left:3px solid var(--oi-border);border-radius:8px}',
    'article[data-source="user"]{border-left-color:var(--oi-user)}',
    'article[data-source="auto"]{border-left-color:var(--oi-auto)}',
    '.oi-meta{color:var(--oi-text-tertiary);font-size:12.5px}',
    '.oi-kind{color:var(--oi-text-secondary);font-weight:600}',
    '.oi-decision{margin:0 0 8px;color:var(--oi-text);white-space:pre-wrap;overflow-wrap:anywhere}',
    '.oi-decision b{font-weight:600}',
    '.oi-excerpt{margin:10px 0 0;padding:8px 12px;border-left:2px solid var(--oi-border);'
      + 'color:var(--oi-text-secondary);font-size:13.5px;white-space:pre-wrap;overflow-wrap:anywhere}',
    '.oi-excerpt figcaption{color:var(--oi-text-tertiary);font-size:12px;margin-bottom:4px}',
    '.oi-empty{color:var(--oi-text-secondary);font-size:14px}',
    '.oi-warning{color:var(--oi-warning)}',
    'footer{margin-top:40px;padding-top:16px;border-top:1px solid var(--oi-border);'
      + 'color:var(--oi-text-tertiary);font-size:12.5px}',
    '@media print{:root{color-scheme:light}body{padding:0;background:var(--oi-print-paper);'
      + 'color:var(--oi-print-ink)}article{break-inside:avoid;page-break-inside:avoid;'
      + 'background:transparent;border-color:#999}h2{break-after:avoid;page-break-after:avoid}}',
    '@media (max-width:560px){body{padding:20px 14px 32px}dt{float:none;width:auto;margin-top:6px}'
      + 'dd{margin-left:0}}',
  ]
  return rules.join('')
}

// ---------------------------------------------------------------------------
// HTML — page
// ---------------------------------------------------------------------------

/** Escaped HTML text; C0/C1 controls become spaces so the page stays parseable. */
const HTML_ESCAPE_PATTERN = /[&<>"']/gu
const HTML_ESCAPES: Readonly<Record<string, string>> = {
  '&': '&amp;',
  '<': '&lt;',
  '>': '&gt;',
  '"': '&quot;',
  "'": '&#39;',
}

/**
 * HTML-escape one text field. Every record-derived string in the page goes
 * through this function; no field is interpolated raw (DESIGN §7.4.7 rule 5).
 * @param text - raw text.
 * @returns escaped text, safe in element content and in a quoted attribute.
 */
export function escapeHtml(text: string): string {
  return text
    .replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f-\u009f]/gu, ' ')
    .replace(HTML_ESCAPE_PATTERN, character => HTML_ESCAPES[character] ?? character)
}

/** Attribute value (same escaping as text; attributes are only used with fixed vocabulary values). */
function attribute(value: string): string {
  return escapeHtml(value)
}

/** One `<article>` per record, with the fixed data attributes of the design. */
function articleOf(record: OpenItemRecord, options: ExportOptions): string {
  const kind = KIND_LABELS[record.kind]
  const resolution = latestResolution(record)
  const header = `<article data-item-id="${attribute(record.id)}" data-source="${attribute(sourceOf(record))}" data-outcome="${attribute(resolution?.kind ?? 'unknown')}">`
  const title = `<h3>${escapeHtml(record.title)}</h3>`
  const meta = `<p class="oi-meta"><span class="oi-kind">${escapeHtml(kind)}</span>`
    + ` · severity ${String(record.severity)}`
    + ` · resolved <time datetime="${escapeHtml(isoUtc(resolvedAtOf(record) ?? Number.NaN))}">`
    + `${escapeHtml(formatUtcInstant(resolvedAtOf(record) ?? Number.NaN))}</time>`
    + ` · ${escapeHtml(sourceLabel(record))}</p>`
  const decision = `<p class="oi-decision"><b>${resolution?.actor === 'detector' ? 'Closed automatically' : 'What you decided'}</b>`
    + ` ${escapeHtml(decisionText(record))}</p>`
  const refs = refRows(record)
  const next = `<dt>What happened next</dt><dd>${escapeHtml(acknowledgementLabel(record))}</dd>`
  const delivery = deliveryRow(record)
  const facts = `<dl class="oi-facts">${refs}${delivery}${next}`
    + `<dt>Archived</dt><dd>${record.retention.class === 'archived' ? 'yes — transcript excerpt dropped' : 'no'}</dd>`
    + `</dl>`
  const excerpt = options.includeExcerpts ? excerptOf(record) : ''
  return [header, title, meta, decision, facts, excerpt, '</article>'].join('')
}

/** The provenance `<dl>` rows: session, event coordinates, item id. */
function refRows(record: OpenItemRecord): string {
  const source = record.source
  const sessionTitle = source.sessionTitle === undefined || source.sessionTitle === ''
    ? '(untitled session)'
    : source.sessionTitle
  const rows: string[] = [
    `<dt>Session</dt><dd>${escapeHtml(sessionTitle)} <code>${escapeHtml(source.sessionId)}</code></dd>`,
  ]
  const coordinates: string[] = []
  if (source.seq !== undefined) coordinates.push(`seq ${String(source.seq)}`)
  if (source.turn !== undefined) coordinates.push(`turn ${String(source.turn)}`)
  if (source.callId !== undefined) coordinates.push(source.callId)
  if (source.messageId !== undefined) coordinates.push(source.messageId)
  if (source.approvalId !== undefined) coordinates.push(source.approvalId)
  if (source.goalId !== undefined) coordinates.push(`goal ${source.goalId}`)
  if (source.taskId !== undefined) coordinates.push(`task ${source.taskId}`)
  if (coordinates.length > 0) {
    rows.push(`<dt>Evidence</dt><dd><code>${escapeHtml(coordinates.join(' · '))}</code></dd>`)
  }
  if (source.workspace?.title !== undefined) {
    rows.push(`<dt>Workspace</dt><dd>${escapeHtml(source.workspace.title)}</dd>`)
  }
  rows.push(`<dt>Item</dt><dd><code>${escapeHtml(record.id)}</code></dd>`)
  return rows.join('')
}

/** The delivery row of the `<dl>`: track, id and state, when a delivery exists. */
function deliveryRow(record: OpenItemRecord): string {
  const latest = record.deliveries[record.deliveries.length - 1]
  if (latest === undefined) return ''
  return `<dt>Delivery</dt><dd>${escapeHtml(latest.track)} · <code>${escapeHtml(latest.deliveryId)}</code>`
    + ` · ${escapeHtml(latest.state)}</dd>`
}

/** The transcript excerpt block, only when excerpts are included and present. */
function excerptOf(record: OpenItemRecord): string {
  const quote = record.quote
  const body = record.body
  const parts: string[] = []
  if (quote !== undefined && quote !== '') {
    parts.push(`<figure class="oi-excerpt"><figcaption>Asked in the session</figcaption><p>${escapeHtml(quote)}</p></figure>`)
  }
  if (body !== '') parts.push(`<p class="oi-excerpt oi-body">${escapeHtml(body)}</p>`)
  return parts.join('')
}

/** The honest `<header>` of the page: schema, plugin, filter, counts, completeness, time. */
function pageHeader(selection: ExportSelection, options: ExportOptions): string {
  const facts = factsOf(selection, options)
  const plural = (count: number): string => `${String(count)} archived record${count === 1 ? '' : 's'}`
  const archived = options.includeArchive
    ? (facts.archivedIncluded === 0
      ? 'included — no archived record matched this filter'
      : `included — ${plural(facts.archivedIncluded)} (transcript excerpt already dropped)`)
    : (facts.archivedExcluded === 0
      ? 'excluded — no archived record matched this filter'
      : `excluded — ${plural(facts.archivedExcluded)} omitted`)
  const completeness = options.earlierRecordsPruned
    ? '<span class="oi-warning">earlier records pruned — this snapshot is not complete</span>'
    : 'complete — nothing pruned'
  const excerpts = options.includeExcerpts ? 'included' : 'excluded'
  return '<header data-export="header">'
    + '<h1>Open items register</h1>'
    + '<p class="oi-meta">What closed, what you chose, and whether the session acted on it.</p>'
    + '<dl class="oi-export-facts">'
    + `<dt>Filter</dt><dd>${escapeHtml(options.filterLabel)}</dd>`
    + `<dt>Records</dt><dd>${String(facts.recordCount)}</dd>`
    + `<dt>Generated</dt><dd><time datetime="${escapeHtml(facts.generatedAt)}">${escapeHtml(formatUtcInstant(options.generatedAt))}</time></dd>`
    + `<dt>Transcript excerpts</dt><dd>${excerpts}</dd>`
    + `<dt>Archive</dt><dd>${escapeHtml(archived)}</dd>`
    + `<dt>Completeness</dt><dd>${completeness}</dd>`
    + `<dt>Version</dt><dd>export schema ${String(EXPORT_SCHEMA_VERSION)} · store schema ${String(options.schemaVersion)}`
    + ` · <code>dsh-open-items ${escapeHtml(options.pluginVersion)}</code></dd>`
    + '</dl>'
    + '<p class="oi-meta">Generated locally by DeepSeek Harness. This file does not load fonts, images, scripts or anything else from a network.</p>'
    + '</header>'
}

/** The `<title>`: deterministic from the filter and count. */
function pageTitle(selection: ExportSelection, options: ExportOptions): string {
  const count = selection.records.length
  return `Open items register — ${String(count)} decision${count === 1 ? '' : 's'} — ${options.filterLabel}`
}

/** Group the sorted records by UTC day, preserving the descending order. */
function groupByDay(records: readonly OpenItemRecord[]): { day: string; records: OpenItemRecord[] }[] {
  const groups: { day: string; records: OpenItemRecord[] }[] = []
  for (const record of records) {
    const at = resolvedAtOf(record)
    const day = at === undefined ? 'unknown-day' : utcDay(at)
    const last = groups[groups.length - 1]
    if (last !== undefined && last.day === day) {
      last.records.push(record)
    } else {
      groups.push({ day, records: [record] })
    }
  }
  return groups
}

/**
 * Chunked self-contained HTML: prefix, then per day a section open, one chunk
 * per article, a section close, then the suffix. Joining the chunks reproduces
 * {@link toHtml} exactly, which is what the download wrapper streams into a Blob.
 * @param selection - filtered result set.
 * @param options - export request.
 * @returns the ordered chunks.
 */
function htmlChunks(selection: ExportSelection, options: ExportOptions): string[] {
  const chunks: string[] = []
  chunks.push('<!DOCTYPE html>\n')
  chunks.push(`<html lang="en">\n<head>\n<meta charset="utf-8">\n`)
  chunks.push('<meta name="viewport" content="width=device-width, initial-scale=1">\n')
  chunks.push(`<meta name="generator" content="dsh-open-items ${escapeHtml(options.pluginVersion)}">\n`)
  chunks.push(`<title>${escapeHtml(pageTitle(selection, options))}</title>\n`)
  chunks.push(`<style>${buildStylesheet()}</style>\n</head>\n<body>\n`)
  chunks.push(pageHeader(selection, options))
  chunks.push('<main data-export="register">\n')
  if (selection.records.length === 0) {
    chunks.push('<p class="oi-empty">No decisions match this filter. Nothing was pruned from an empty result.</p>\n')
  }
  for (const group of groupByDay(selection.records)) {
    const count = group.records.length
    chunks.push(`<section data-day="${attribute(group.day)}">\n<h2>${escapeHtml(formatDayHeading(group.day))}`
      + ` <span class="oi-meta">· ${String(count)} decision${count === 1 ? '' : 's'}</span></h2>\n`)
    for (const record of group.records) chunks.push(`${articleOf(record, options)}\n`)
    chunks.push('</section>\n')
  }
  chunks.push('</main>\n')
  chunks.push('<footer data-export="footer"><p>'
    + 'Resolutions are recorded exactly as they were submitted; nothing in this page was regenerated by a model. '
    + 'The page is a snapshot of the filter named above.'
    + '</p></footer>\n')
  chunks.push('</body>\n</html>\n')
  return chunks
}

/**
 * Deterministic self-contained HTML page: frozen stylesheet, no scripts, no
 * external references, escaped text, fixed DOM attributes, grouped by UTC day.
 * @param records - records in any order.
 * @param options - export request.
 * @returns the complete page.
 */
export function toHtml(records: readonly OpenItemRecord[], options: ExportOptions): string {
  return htmlChunks(selectExportRecords(records, options), options).join('')
}

// ---------------------------------------------------------------------------
// Chunks and the single entry point
// ---------------------------------------------------------------------------

/**
 * Generate one export as ordered chunks. This is the streaming entry point: the
 * download wrapper builds a `Blob` from the chunks, so a large register never
 * becomes one giant string in memory first.
 * @param records - records in any order.
 * @param options - export request.
 * @returns the chunk set, file name, MIME type and exact UTF-8 byte length.
 */
export function exportChunks(records: readonly OpenItemRecord[], options: ExportOptions): ExportChunkSet {
  const selection = selectExportRecords(records, options)
  const chunks = options.format === 'csv'
    ? csvChunks(selection, options)
    : options.format === 'jsonl'
      ? jsonlChunks(selection, options)
      : htmlChunks(selection, options)
  let byteLength = 0
  for (const chunk of chunks) byteLength += utf8ByteLength(chunk)
  return {
    format: options.format,
    filename: exportFileName(selection, options),
    mimeType: EXPORT_MIME_TYPES[options.format],
    chunks,
    byteLength,
  }
}

/**
 * Generate one export as a single string (golden files, tests, clipboard-ish
 * consumers). The download path uses {@link exportChunks} instead.
 * @param records - records in any order.
 * @param options - export request.
 * @returns the file, its name, MIME type and byte length.
 */
export function generateExport(records: readonly OpenItemRecord[], options: ExportOptions): ExportFile {
  const chunkSet = exportChunks(records, options)
  const content = chunkSet.chunks.join('')
  return {
    format: chunkSet.format,
    filename: chunkSet.filename,
    mimeType: chunkSet.mimeType,
    content,
    byteLength: chunkSet.byteLength,
  }
}

/**
 * UTF-8 byte length of one string, without `TextEncoder`/`Buffer` so the module
 * stays environment-free. Lone surrogates encode as three bytes (U+FFFD), which
 * is what a UTF-8 encoder does.
 * @param text - any string.
 * @returns its UTF-8 byte length.
 */
export function utf8ByteLength(text: string): number {
  let bytes = 0
  for (let index = 0; index < text.length; index += 1) {
    const code = text.charCodeAt(index)
    if (code < 0x80) {
      bytes += 1
    } else if (code < 0x800) {
      bytes += 2
    } else if (code >= 0xd800 && code <= 0xdbff) {
      const next = index + 1 < text.length ? text.charCodeAt(index + 1) : 0
      if (next >= 0xdc00 && next <= 0xdfff) {
        bytes += 4
        index += 1
      } else {
        bytes += 3
      }
    } else {
      bytes += 3
    }
  }
  return bytes
}
